const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el sintetizador de sesiones de RAX.\nTu labor es procesar notas o transcripciones autorizadas para extraer acuerdos y propuestas de tareas.\nREGLAS FUNDAMENTALES:\n1. Todo compromiso extraído debe incluir una cita literal de origen (sourceQuote).\n2. No inventes responsables ni fechas límite. Si no se dijeron explícitamente, déjalos como null o 'no especificado'.\n3. Distingue entre 'decisiones acordadas' (agreements) y 'tareas pendientes' (tasks).\n4. Salida en formato JSON estricto con: summary (string), topicsCovered (array), agreements (array de objetos con title, sourceQuote), suggestedTasks (array de objetos con title, ownerSuggestion, dueDateSuggestion, successCriteria, sourceQuote), openQuestions (array), uncertainties (array).`;

const userPrompt = JSON.stringify({
  sessionId: event.entityId,
  sessionKind: payload.sessionKind,
  rawNotes: payload.rawNotes || payload.notes || '',
  mentorId: event.actor?.id,
  projectId: event.projectId
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'http://localhost:3000') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    systemPrompt,
    userPrompt
  }
}];

const response = $input.first().json;
const prep = $('Build Synthesis Prompt').first().json;

let parsed = {};
try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    summary: 'Error al interpretar la síntesis de sesión',
    uncertainties: ['Salida JSON no válida del modelo']
  };
}

const taskProposals = (parsed.suggestedTasks || []).map(task => ({
  type: 'task',
  title: task.title,
  description: task.description || '',
  ownerSuggestion: task.ownerSuggestion || undefined,
  dueDateSuggestion: task.dueDateSuggestion || undefined,
  successCriteria: task.successCriteria || undefined,
  sourceQuote: task.sourceQuote || undefined,
  needsHumanApproval: true,
  uncertainties: []
}));

const agreementProposals = (parsed.agreements || []).map(agr => ({
  type: 'goal',
  title: typeof agr === 'string' ? agr : agr.title,
  sourceQuote: typeof agr === 'object' ? agr.sourceQuote : undefined,
  needsHumanApproval: true,
  uncertainties: []
}));

const callbackPayload = {
  operationId: 'op_syn_' + Date.now(),
  correlationId: prep.correlationId,
  workflowId: 'RAX-06',
  workflowVersion: '1.0.0',
  status: 'completed',
  usage: {
    model: response.model || prep.model,
    promptTokens: response.usage?.prompt_tokens || 0,
    completionTokens: response.usage?.completion_tokens || 0
  },
  data: {
    summary: parsed.summary,
    proposals: [...taskProposals, ...agreementProposals],
    uncertainties: parsed.uncertainties || [],
    nextStepRecommendation: (parsed.openQuestions || []).join('; ')
  }
};

return [{
  json: {
    callbackUrl: prep.callbackUrl,
    payload: callbackPayload
  }
}];
